  "Du": "Du",
  "Du behöver ett koppel – köp ett i djuraffären.": "Du brauchst eine Leine – kauf eine im Zooladen.",
  "Du behöver tjäna <b>{0}</b> till – ungefär <b>{1} pass</b> (≈ {2} per pass).": "Du musst noch <b>{0}</b> verdienen – ungefähr <b>{1} Schichten</b> (≈ {2} pro Schicht).",
