  "Du bor ihop med {0} – flytta isär först (👥 i menyraden).": "Du wohnst mit {0} zusammen – zieht erst auseinander (👥 in der Menüleiste).",
  "Du bor redan här.": "Du wohnst schon hier.",
  "Du bär ingenting.": "Du trägst nichts.",
  "Du bär på <b>{0}</b> ({1}) som inte är betald.": "Du trägst <b>{0}</b> ({1}), das noch nicht bezahlt ist.",
  "Du flyttar tillbaka till {0} med dina gamla möbler.": "Du ziehst mit deinen alten Möbeln zurück in dein Zuhause: {0}.",
  "Du får <b>{0}</b> nu. Betala tillbaka <b>{1}</b> (lånet + {2} % ränta) senast <b>{3}</b> så får du tillbaka möbeln. Annars behåller pantbanken den.": "Du bekommst jetzt <b>{0}</b>. Zahl <b>{1}</b> (Kredit + {2} % Zinsen) bis spätestens <b>{3}</b> zurück, dann bekommst du das Möbelstück wieder. Sonst behält es das Pfandhaus.",
  "Du får den i handen och sätter dig vid bistroborden här bredvid – mättheten kommer medan du äter.": "Du bekommst es direkt in die Hand und setzt dich an die Bistrotische hier nebenan – satt wirst du beim Essen.",
  "Du får en bricka och sätter dig vid ett ledigt bord. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Du bekommst ein Tablett und setzt dich an einen freien Tisch. Sättigung und Energie kommen beim Essen – aber nur im Sitzen!",
